import{z as B,x as l,o as E,c as s,q as n,j as r,D as e,d as i,s as t,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"内部人交易理论","description":"","frontmatter":{"title":"内部人交易理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/insider-trading-theory.md","filePath":"econ/insider-trading-theory.md","lastUpdated":1791063341000}'),d={name:"econ/insider-trading-theory.md"};function p(h,a,m,c,_,D){const A=l("Mermaid");return E(),s("div",null,[a[2]||(a[2]=n('<h1 id="内部人交易理论" tabindex="-1">内部人交易理论 <a class="header-anchor" href="#内部人交易理论" aria-label="Permalink to &quot;内部人交易理论&quot;">​</a></h1><div class="epigraph"><p>内部人按私人信息交易，使价格更快吸收信息，也把流动性供给者置于信息劣势；效率与分配的权衡，不是一句「禁止就公平」能结束。</p><footer>—— Manne, Insider Trading and the Stock Market, 1966；Leland, Insider Trading: Should It Be Prohibited, Journal of Political Economy 1992；Fishman and Hagerty, Journal of Finance 1992</footer></div><p><a href="/econ/law-and-finance">上一课</a>把法律写成保护参数。内部人交易规则是证券法的一块。本课缺口是理论：允许经理交易是否改善价格信息、是否扭曲投资与薪酬。不重写 LLSV 指数，不把限价簿上的知情交易模型写成量化栏微观结构主线——只取对公司合同的含义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Manne：内部人交易是对经理信息生产的补偿，价格更准。反驳：流动性交易者受损，买卖价差上升，外部股权更贵（接 LLSV 参与约束）；经理可能操纵信息披露时点来交易，投资选择变成「制造可交易波动」。Leland（1992）：一般均衡里，内部人交易提高价格信息、可能改善投资，但也转移风险、可能降低对外融资意愿。Fishman–Hagerty：内部人挤出外部分析师的信息生产。缺口是把「信息进入价格」接到治理，而不是重画 Kyle 曲线——<a href="/econ/kyle-in-equilibrium">Kyle 在均衡中</a>已有价格影响语言，本课不进入限价簿协议。</p><p><span class="marginnote">效率：价格是否更接近 \\(v\\)。分配：谁从信息租金获利。流动性：外部人是否还愿意做对手方。三句话必须分开。</span><span class="marginnote">术语翻译：MNPI（重大非公开信息）就是「还没公告、但一旦公告就会让股价动」的消息，比如并购或业绩变脸。禁令管的不是「经理不准买卖自家股票」，而是「不准趁消息没公开先下手」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>允许交易：薪酬可以更低现金、更高信息租金，但董事会更难用股价做合同——股价含经理自己的交易噪声与激励扭曲。禁止并强制披露：信息改走新闻，经理用薪酬与持股激励，内部人租金下降，价差可能下降。现实是部分禁止（基于重大非公开信息）加披露（Form 4），不是角点。</p><p>对公司金融：内部人买卖是信号（与股利信号近亲），也是代理（抢外部股东）。优序的发股窗口若配内部人减持，柠檬更重。择时课的「经理认为高估」与内部人出售观测相关，但合法计划交易使识别变难。</p>',9)),(E(),r(o,null,{default:e(()=>[t(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INFO%5B%22%E7%BB%8F%E7%90%86%E7%9F%A5%E6%83%85%22%5D%20--%3E%20TRADE%5B%22%E5%86%85%E9%83%A8%E4%BA%BA%E4%BA%A4%E6%98%93%22%5D%0A%20%20TRADE%20--%3E%20PX%5B%22%E4%BB%B7%E6%A0%BC%E6%9B%B4%E4%BF%A1%E6%81%AF%3F%22%5D%0A%20%20TRADE%20--%3E%20LIQ%5B%22%E5%A4%96%E9%83%A8%E4%BA%BA%E4%BB%B7%E5%B7%AE%E4%B8%8A%E5%8D%87%22%5D%0A%20%20TRADE%20--%3E%20INV%5B%22%E6%8A%95%E8%B5%84%E4%B8%BA%E4%BA%86%E5%8F%AF%E4%BA%A4%E6%98%93%E4%BF%A1%E6%81%AF%22%5D%0A%20%20BAN%5B%22%E7%A6%81%E6%AD%A2%20%2B%20%E6%8A%AB%E9%9C%B2%22%5D%20--%3E%20COMP%5B%22%E6%94%B9%E7%94%A8%E8%96%AA%E9%85%AC%E6%BF%80%E5%8A%B1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p>与双层：控股股东内部人交易加楔子，掏空可以走交易而不走股利。保护参数决定执法概率，从而决定租金期望值。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是信息租金与市场参与。价格发现是公共品，内部人提供一部分、挤出另一部分。投资扭曲：项目若产生不可交易的长期价值，经理更少做；若产生可提前交易的消息，过多做。这与多任务薪酬同构，度量换成价格路径。</p><p>宏观与披露管制：强制披露把信息公共化，减少内部人租金，也减少「用交易补偿经理」的通道，董事会必须把激励写回合同。</p><h3 id="不是微观结构课" tabindex="-1">不是微观结构课 <a class="header-anchor" href="#不是微观结构课" aria-label="Permalink to &quot;不是微观结构课&quot;">​</a></h3><p>知情交易如何改变簿上价差，量化栏写。本栏停在：参与约束、薪酬替代、投资扭曲、与发股柠檬的互动。不要把做市商库存当成本文。</p><p><span class="marginnote">Manne 1966 是论辩起点。Leland <em>JPE</em> 1992 提供一般均衡权衡。规范结论随福利权重而变，本课不立法。</span></p><p><span class="marginnote">常见误区：初学者容易以为「内部人赚的钱只来自自愿卖给他的人，不伤别人」。实际上做市商用更宽的价差自保，价差由所有交易者分摊，融资成本上升再由全体股东分摊——租金是从整个市场抽走的。</span></p>',8)),(E(),r(o,null,{default:e(()=>[t(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E7%BB%8F%E7%90%86%E7%9F%A5%E9%81%93%E5%A5%BD%E6%B6%88%E6%81%AF%22%5D%20--%3E%20BUY%5B%22%E5%85%AC%E5%91%8A%E5%89%8D%E6%8F%90%E5%89%8D%E4%B9%B0%E5%85%A5%22%5D%0A%20%20LIQ%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E4%BA%A4%E6%98%93%E8%80%85%22%5D%20--%3E%20SELL%5B%22%E6%8C%89%E6%9C%AA%E5%90%AB%E4%BF%A1%E6%81%AF%E7%9A%84%E6%97%A7%E4%BB%B7%E5%8D%96%E5%87%BA%22%5D%0A%20%20BUY%20--%3E%20RENT%5B%22%E5%86%85%E9%83%A8%E4%BA%BA%E8%B5%9A%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%22%5D%0A%20%20RENT%20--%3E%20SPREAD%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E5%8A%A0%E5%AE%BD%E4%BB%B7%E5%B7%AE%E8%87%AA%E4%BF%9D%22%5D%0A%20%20SPREAD%20--%3E%20COST%5B%22%E5%A4%96%E9%83%A8%E8%82%A1%E6%9D%83%E4%B8%8E%E8%9E%8D%E8%B5%84%E6%9B%B4%E8%B4%B5%22%5D%0A%20%20COST%20--%3E%20ALL%5B%22%E6%88%90%E6%9C%AC%E7%94%B1%E5%85%A8%E4%BD%93%E8%82%A1%E4%B8%9C%E5%88%86%E6%91%8A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成内幕法条。下一课公司对冲：经理用衍生品降低可交易风险与职业风险，可能与股东要的风险不一致——对冲是另一套「谁的风险」。现金持有则是流动性与代理。</p><p>后课默认：内部人交易在价格信息与流动性/投资扭曲之间权衡；禁止把激励赶回薪酬合同。本栏不重写限价簿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内部人交易可加快价格发现，也提高外部人成本、扭曲投资与披露时点。</li><li>与薪酬、发股柠檬、楔子下的掏空相连。</li><li>效率、分配、流动性三句分开；法律是 LLSV 保护的一块。</li><li>出处：Manne 1966；Leland, <em>JPE</em> 1992；Fishman and Hagerty, <em>JF</em> 1992。</li></ul>',5))])}const f=B(d,[["render",p]]);export{u as __pageData,f as default};
